    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead matching: reward bins where the post_residual can perfectly or closely fit the next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact fit or near-exact fit (high priority).
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - diff) * 0.8;
