    // 3. Balance usage: if this is the only bin that fits, prioritize it heavily to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 4. Strategic new-bin constraint: only open a new bin if the current fit is extremely poor (large post_residual).
    if bin_residual == bin_capacity {
        // Only consider a new bin if the mean residual of existing bins is already small (tight packing),
        // or if we are forced to create a very inefficient fit in all currently open bins.
        if mean_residual > 20.0 {
            score += 40.0; 
