pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Base score: prioritize smaller post_residual (Best Fit principle)
    // We penalize larger residual spaces quadratically to favor tight packing.
    let mut score = post * post / capacity;

    // Lookahead logic: if next_item_size is large, avoid leaving a small gap that 
    // nothing can use. If post_residual is smaller than next_item_size, it's a "dead space" trap.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post).powi(2) * 0.5;
        }
    }

    // Dynamic pressure: As the stream progresses, increase the penalty for opening 
    // new bins by making the "new bin" candidate (where bin_residual == bin_capacity) 
    // increasingly expensive compared to filling existing bins.
    if bin_residual == bin_capacity {
        // The cost of opening a new bin scales with progress.
        // We prefer to pack into existing bins late in the stream.
        score += (capacity * 0.5) * (1.0 + progress);
    } else {
        // Reward bins that have residuals close to the global mean, 
        // promoting uniform bin usage (balancing load).
        let deviation = (post - mean_residual).abs();
        score -= deviation * 0.2;
    }

    // If this is the only bin that can fit the item, prioritize it heavily 
    // to avoid unnecessary fragmentation or new bin overhead.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

