    // We penalize residuals that are small but not zero (fragmentation).
    if post_residual > 0 && post_residual < 20 {
        score += 45.0;
    }

    // 2. Harmonic refinement: Use modulo to favor bins that reach clean fractions of capacity.
    // If post_residual is a divisor of capacity, it's more likely to fit future items.
    if post_residual > 0 && (bin_capacity % post_residual == 0) {
        score -= 15.0;
    }

    // 3. Lookahead logic: If next_item_size is known, prioritize bins that will fit it perfectly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let diff = (post_residual - next_item_size) as f64;
            score += diff * 0.5; // Favor tighter fits for the lookahead item
        } else {
            score += 30.0; // Penalize bins that cannot accommodate the next item
        }
    }

    // 4. Strategic New Bin Threshold:
    // If this is a new bin (bin_residual == bin_capacity), only pick it if the current
    // fitting options are poor (high post_residual).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 40.0; // Heavy bias against opening new bins unless necessary
        }
    } else {
        // Encourage filling existing bins when they are already somewhat full
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 10.0;
    }

    // 5. Global pressure: As we approach the end of the stream, prioritize efficiency over flexibility.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
