pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual while penalizing "dead zones" (1-9) 
    // and controlling the number of open bins based on stream progress.

    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residues that are hard to fill).
    // If post_residual is between 1 and 9, it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64).sqrt();
    }

    // 2. Lookahead optimization: If the next item fits into the current post_residual, 
    // reward this placement heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 3. Dynamic pressure: In the early stages, prioritize filling existing bins.
    // As the stream nears completion, become more aggressive in opening new bins
    // if it helps preserve better fits for the remaining items.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 - progress) * 2.0;

    // 4. New Bin Logic: If this is a new bin (bin_residual == bin_capacity),
    // only choose it if the penalty for fitting into existing bins is high.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is high to encourage Best-Fit behavior.
        // We reduce this penalty if we have many open bins that are nearly full 
        // or if the current item is very large.
        score = 45.0 + (item_size as f64 * 0.5);
    } else {
        // If it's a tight fit (post_residual is small), reward the bin selection.
        if post_residual < 10 {
            score -= 10.0;
        }
    }

    // 5. Anti-fragmentation: If this bin is the only one that can fit the item,
    // force its selection by lowering the score significantly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic: Harmonic Best-Fit with Lookahead Penalty
    // Goal: Minimize post_residual while avoiding "fragmentation traps" (small residuals)
    // and utilizing lookahead to preserve space for incoming items.

    let mut score = post_residual as f64;

    // 1. Fragmentation Penalty: Penalize residuals that are too small to fit common items
    // (e.g., if post_residual is in (0, 10), it is likely wasted space).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Harmonic Alignment: Favor residuals that are multiples of common item sizes (e.g., 20, 25, 33)
    // This helps keep bins "clean" for future items.
    let harmonic_mod = post_residual % 20;
    score += harmonic_mod as f64 * 0.5;

    // 3. Lookahead Logic: If the next item is large, prioritize bins that keep enough space.
    // If post_residual is smaller than next_item_size, we effectively force a new bin later.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        } else {
            // Bonus for keeping space specifically for the next item
            score -= 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // 4. Global Density Control: Favor filling bins that are close to the mean to minimize open bin count.
    let residual_deviation = (bin_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.1;

    // 5. Threshold for New Bin:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Only open a new bin if the current fitting options are extremely poor (high score).
    if bin_residual == bin_capacity {
        score = 25.0; // Baseline cost to open a new bin
    }

    // 6. Scarcity Penalty: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the "New Bin" case heavily early in the stream, 
    // but allow it if current bins are very fragmented (high mean_residual).
    let is_new_bin = bin_residual == bin_capacity;
    let base_score = if is_new_bin {
        (1.0 - progress) * 150.0 + (mean_residual * 0.5)
    } else {
        post
    };

    // Interaction term: penalize small residuals that create "unfillable" gaps 
    // (e.g., < 10) unless it's a perfect fit (post == 0).
    let gap_penalty = if post > 0.0 && post < 10.0 {
        15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Lookahead coupling: If a second item is known, penalize bins that 
    // leave too little room for it, effectively implementing a "Best Fit" 
    // variant that respects potential future needs.
    let lookahead_penalty = if next_item_size > 0 && (post as u32) < next_item_size {
        (next_item_size as f64 - post) * 2.5
    } else {
        0.0
    };

    // Global pressure: as the stream nears the end, prioritize closing bins
    // by heavily penalizing keeping many bins open (open_bins_count).
    let closure_incentive = (open_bins_count as f64) * progress * 5.0;

    base_score + gap_penalty + lookahead_penalty + closure_incentive
}
